import unittest
from tickets import list_tickets


class StatusFilter(unittest.TestCase):
    def setUp(self):
        self.tickets = [
            {"id": 1, "status": "open"},
            {"id": 2, "status": "closed"},
            {"id": 3, "status": "open"},
        ]

    def test_open(self):
        self.assertEqual([x["id"] for x in list_tickets(self.tickets, "open")], [1, 3])

    def test_closed(self):
        self.assertEqual([x["id"] for x in list_tickets(self.tickets, "closed")], [2])

    def test_unknown(self):
        self.assertEqual(list_tickets(self.tickets, "unknown"), [])

"""Ticket listing baseline: optional status is not implemented yet."""


def list_tickets(tickets, status=None):
    return [dict(ticket) for ticket in tickets]

import unittest
from tickets import list_tickets


class Compatibility(unittest.TestCase):
    def test_default_preserves_order_and_fields(self):
        rows = [
            {"id": 2, "status": "open", "title": "two"},
            {"id": 1, "status": "closed"},
        ]
        self.assertEqual(list_tickets(rows), rows)

    def test_returns_copies(self):
        row = {"id": 1, "status": "open"}
        out = list_tickets([row])
        out[0]["id"] = 9
        self.assertEqual(row["id"], 1)

    def test_empty(self):
        self.assertEqual(list_tickets([]), [])
